import{_ as l,a0 as p,w as o,s as d,ao as r,I as n,x as t,a1 as a,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"Bash 基础知识系列 #3：传递参数和接受用户输入 | LCTT x X-CMD","titleTemplate":false,"description":"Bash 基础知识系列 #3：传递参数和接受用户输入 | LCTT (202307) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Bash 基础知识系列 #3：传递参数和接受用户输入 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Bash 基础知识系列 #3：传递参数和接受用户输入 | LCTT (202307) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202307/20230626.0 ⭐️⭐️ Bash Basics Series 3 Passing Arguments and Accepting User Inputs","title":"Bash 基础知识系列 #3：传递参数和接受用户输入","tag":"202307","desc":""},"relativePath":"202307/20230626.0 ⭐️⭐️ Bash Basics Series 3 Passing Arguments and Accepting User Inputs.md","filePath":"[post].md"}'),h={name:"202307/20230626.0 ⭐️⭐️ Bash Basics Series 3 Passing Arguments and Accepting User Inputs.md"};function c(g,s,u,b,k,m){const e=p("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="bash-基础知识系列-3-传递参数和接受用户输入" tabindex="-1">Bash 基础知识系列 #3：传递参数和接受用户输入 <a class="header-anchor" href="#bash-基础知识系列-3-传递参数和接受用户输入" aria-label="Permalink to “Bash 基础知识系列 #3：传递参数和接受用户输入”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202307/15/094330dzt3s3ygshsst39t.jpg" alt=""></p><blockquote><p>在 Bash 基础系列的这一章中，学习如何向 Bash 脚本传递参数并使它们具有交互性。</p></blockquote><p>来让 Bash 脚本有参数吧 😉</p><p>你可以通过向 Bash 脚本传递变量来使其更加有用和更具交互性。</p><p>让我通过示例详细向你展示这一点。</p><h3 id="将参数传递给-shell-脚本" tabindex="-1">将参数传递给 Shell 脚本 <a class="header-anchor" href="#将参数传递给-shell-脚本" aria-label="Permalink to “将参数传递给 Shell 脚本”">​</a></h3><p>当你运行 Shell 脚本时，你可以按以下方式向其中添加其他变量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./my_script.sh var1 var2</span></span></code></pre></div><p>在脚本内部，你可以使用 <code>$1</code> 作为第一个参数，<code>$2</code> 作为第二个参数，依此类推。</p><blockquote><p>💡 <code>$0</code> 是一个特殊变量，保存正在执行的脚本的名称。</p></blockquote><p>让我们通过一个实际的例子来看看。切换到保存练习 Bash 脚本的目录。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir -p bash_scripts &amp;&amp; cd bash_scripts</span></span></code></pre></div><p>现在，创建一个名为 <code>arguments.sh</code> （我想不出更好的名称）的新 Shell 脚本，并向其中添加以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo &quot;Script name is: $0&quot;</span></span>
<span class="line"><span>echo &quot;First argument is: $1&quot;</span></span>
<span class="line"><span>echo &quot;Second argument is: $2&quot;</span></span></code></pre></div><p>保存文件并使其可执行。现在像往常一样运行脚本，但这次向其中添加任意两个字符串。你将看到屏幕上打印的详细信息。</p><blockquote><p>🚧 参数由空格（空格、制表符）分隔。如果参数中有空格，请使用（英文）双引号将其引起来，否则它将被视为单独的参数。</p></blockquote><p><img src="https://itsfoss.com/content/images/2023/06/run-bash-script-with-arguments.png" alt="Pass arguments to the bash scripting"></p><blockquote><p>💡 Bash 脚本最多支持 255 个参数。但对于参数 10 及以上，你必须使用花括号 <code>\${10}</code>、<code>\${11}</code>...<code>\${n}</code>。</p></blockquote><p>正如你所看到的，<code>$0</code> 代表脚本名称，而其余参数存储在编号变量中。你还可以在脚本中使用一些其他特殊变量。</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">特殊变量</th><th style="text-align:left;">变量描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>$0</code></td><td style="text-align:left;">脚本名称</td></tr><tr><td style="text-align:left;"><code>$1</code>、<code>$2</code>、……<code>$9</code></td><td style="text-align:left;">脚本参数</td></tr><tr><td style="text-align:left;"><code>\${n}</code></td><td style="text-align:left;">脚本参数从 10 到 255</td></tr><tr><td style="text-align:left;"><code>$#</code></td><td style="text-align:left;">参数数量</td></tr><tr><td style="text-align:left;"><code>$@</code></td><td style="text-align:left;">所有参数</td></tr><tr><td style="text-align:left;"><code>$$</code></td><td style="text-align:left;">当前 Shell 的进程 ID</td></tr><tr><td style="text-align:left;"><code>$!</code></td><td style="text-align:left;">最后执行的命令的进程 ID</td></tr><tr><td style="text-align:left;"><code>$?</code></td><td style="text-align:left;">最后执行命令的退出状态</td></tr></tbody></table></div><blockquote><p>🏋️‍♀️ 修改上面的脚本以显示参数数量。</p></blockquote><h4 id="如果参数数量不匹配怎么办" tabindex="-1">如果参数数量不匹配怎么办？ <a class="header-anchor" href="#如果参数数量不匹配怎么办" aria-label="Permalink to “如果参数数量不匹配怎么办？”">​</a></h4><p>在上面的示例中，你为 Bash 脚本提供了两个参数并在脚本中使用了它们。</p><p>但是，如果你只提供一个参数或三个参数怎么办？</p><p>让我们实际做一下吧。</p><p><img src="https://itsfoss.com/content/images/2023/06/passing-non-matching-arguments-bash-shell.png" alt="Passing fewer or more arguments to bash script"></p><p>正如你在上面所看到的，当你提供的参数超出预期时，结果仍然是一样的。不使用其他参数，因此不会产生问题。</p><p>但是，当你提供的参数少于预期时，脚本将显示空白。如果脚本的一部分依赖于缺少的参数，这可能会出现问题。</p><h3 id="接受用户输入并制作交互式-bash-脚本" tabindex="-1">接受用户输入并制作交互式 Bash 脚本 <a class="header-anchor" href="#接受用户输入并制作交互式-bash-脚本" aria-label="Permalink to “接受用户输入并制作交互式 Bash 脚本”">​</a></h3><p>你还可以创建提示用户通过键盘提供输入的 Bash 脚本。这使你的脚本具有交互性。</p><p><code>read</code> 命令提供了此功能。你可以这样使用它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo &quot;Enter something&quot;</span></span>
<span class="line"><span>read var</span></span></code></pre></div><p>上面的 <code>echo</code> 命令不是必需的，但最终用户不会知道他们必须提供输入。然后用户在按回车键之前输入的所有内容都存储在 <code>var</code> 变量中。</p><p>你还可以显示提示消息并在单行中获取值，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>read -p &quot;Enter something? &quot; var</span></span></code></pre></div><p>让我们看看它的实际效果。创建一个新的 <code>interactive.sh</code> Shell 脚本，内容如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo &quot;What is your name, stranger?&quot;</span></span>
<span class="line"><span>read name</span></span>
<span class="line"><span>read -p &quot;What&#39;s your full name, $name? &quot; full_name</span></span>
<span class="line"><span>echo &quot;Welcome, $full_name&quot;</span></span></code></pre></div><p>在上面的示例中，我使用 <code>name</code> 变量来获取名称。然后我在提示中使用 <code>name</code> 变量，并在 <code>full_name</code> 变量中获取用户输入。我使用了两种使用 <code>read</code> 命令的方法。</p><p>现在，如果你授予执行权限，然后运行此脚本，你会注意到该脚本显示 <code>What is your name, stranger?</code>，然后等待你从键盘输入内容。你提供输入，然后它会显示 <code>What&#39;s your full name</code> 消息，并再次等待输入。</p><p>以下是供你参考的示例输出：</p><p><img src="https://itsfoss.com/content/images/2023/06/interactive-bash-shell-script.png" alt="Interactive bash shell script"></p><h3 id="🏋️-练习时间" tabindex="-1">🏋️ 练习时间 <a class="header-anchor" href="#🏋️-练习时间" aria-label="Permalink to “🏋️ 练习时间”">​</a></h3><p>是时候练习你所学到的东西了。尝试为以下场景编写简单的 Bash 脚本。</p><p><strong>练习 1</strong>：编写一个带有三个参数的脚本。你必须使脚本以相反的顺序显示参数。</p><p>预期输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>abhishek@itsfoss:~/bash_scripts$ ./reverse.sh ubuntu fedora arch</span></span>
<span class="line"><span>Arguments in reverse order:</span></span>
<span class="line"><span>arch fedora ubuntu</span></span></code></pre></div><p><strong>练习 2</strong>：编写一个脚本，显示传递给它的参数数量。</p><p>提示：使用特殊变量 <code>$#</code>。</p><p>预期输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>abhishek@itsfoss:~/bash_scripts$ ./arguments.sh one and two and three</span></span>
<span class="line"><span>Total number of arguments: 5</span></span></code></pre></div><p><strong>练习 3</strong>：编写一个脚本，将文件名作为参数并显示其行号。</p><p>提示：使用 <code>wc</code> 命令来计算行号。</p><p>你可以在社区中讨论你的解决方案。</p><p>很好！ 现在你可以（传递）参数了 😃 在下一章中，你将学习在 Bash 中执行基本数学运算。</p><p><em>（题图：MJ/5a75aa2f-1cb1-4009-a4e6-683cf61bc892）</em></p><hr>`,57)),n("p",null,[s[1]||(s[1]=t("via: ",-1)),a(e,{href:"https://itsfoss.com/bash-pass-arguments/"},{default:i(()=>[...s[0]||(s[0]=[t("https://itsfoss.com/bash-pass-arguments/",-1)])]),_:1})]),n("p",null,[s[6]||(s[6]=t("作者：",-1)),a(e,{href:"https://itsfoss.com/author/abhishek/"},{default:i(()=>[...s[2]||(s[2]=[t("Abhishek Prakash",-1)])]),_:1}),s[7]||(s[7]=t(" 选题：",-1)),a(e,{href:"https://github.com/lkxed/"},{default:i(()=>[...s[3]||(s[3]=[t("lkxed",-1)])]),_:1}),s[8]||(s[8]=t(" 译者：",-1)),a(e,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[t("geekpi",-1)])]),_:1}),s[9]||(s[9]=t(" 校对：",-1)),a(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[t("wxy",-1)])]),_:1})]),n("p",null,[s[12]||(s[12]=t("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[t("LCTT",-1)])]),_:1}),s[13]||(s[13]=t(" 原创编译，",-1)),a(e,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[t("Linux中国",-1)])]),_:1}),s[14]||(s[14]=t(" 荣誉推出",-1))])])}const v=l(h,[["render",c]]);export{x as __pageData,v as default};
